import{_ as t,o as s,c as i,ag as e}from"./chunks/framework.C9sp7nFj.js";const k=JSON.parse('{"title":"SetColliParam 设置碰撞检测参数","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/5. 设置指令/SetColliParam.md","filePath":"3. 指令/5. 设置指令/SetColliParam.md","lastUpdated":1778862643000}'),l={name:"3. 指令/5. 设置指令/SetColliParam.md"};function n(d,a,r,o,h,p){return s(),i("div",null,[...a[0]||(a[0]=[e(`<h1 id="setcolliparam-设置碰撞检测参数" tabindex="-1">SetColliParam 设置碰撞检测参数 <a class="header-anchor" href="#setcolliparam-设置碰撞检测参数" aria-label="Permalink to &quot;SetColliParam 设置碰撞检测参数&quot;">​</a></h1><p>该指令用于手动配置机器人各关节轴的碰撞检测开关状态及具体的灵敏度百分比。通过为不同轴设定差异化的阈值，可以实现更灵活的安全保护策略，例如在复杂工况下加强末端轴的灵敏度，或放宽大负载轴的限制。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>SetColliParam(colliId, AxisID, Valid, Value) SetColliParam(碰撞参数, 轴号, 有效性, 灵敏度值)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>[colliId] 碰撞参数 (colliId)</td><td>COLLIPARAM 变量</td><td>碰撞检测功能所引用的参数组。</td><td>可缺省，默认为系统出厂的 <code>DEFAULT</code> 参数。</td></tr><tr><td>AxisID：轴号</td><td>枚举型</td><td>* <code>GROUP</code>：所有轴<br>* <code>A1-A6</code>：对应 1 至 6 轴<br>* <code>DEFAULT</code>：无意义</td><td></td></tr><tr><td>Valid：有效性</td><td>枚举型</td><td>* <code>ENABLE</code>：开启检测<br>* <code>DISABLE</code>：关闭检测</td><td>仅在轴号为非 <code>DEFAULT</code> 时有效。</td></tr><tr><td>Value：灵敏度值</td><td>整型</td><td>单位为百分比 (<strong>%)</strong>，取值范围 <strong>1~500</strong>。数值越小越灵敏。</td><td>仅在轴号为非 <code>DEFAULT</code> 时有效。</td></tr></tbody></table><hr><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>碰撞检测系统通过实时监控电机电流并与动力学模型计算出的理论力矩进行比对。该指令通过调整 <code>Value</code>（灵敏度值）来改变允许的偏差范围。当偏差超过 <code>Value</code> 设定的百分比阈值时，系统判定发生碰撞并触发停机保护。</p><hr><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 示例 1：开启全部轴的碰撞检测，灵敏度设为 100%</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetColliParam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(COLLI1, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;GROUP&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ENABLE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 示例 2：针对末端 6 轴进行强化保护，灵敏度设为 50%</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetColliParam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(COLLI1, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;A6&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ENABLE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="执行结果" tabindex="-1">执行结果 <a class="header-anchor" href="#执行结果" aria-label="Permalink to &quot;执行结果&quot;">​</a></h3><p>指令执行后，对应的轴会立即应用新的开关状态和灵敏度。如果后续运动中该轴受到的外力矩偏差超过了设定的百分比阈值，机器人将立即停止运动，并产生相应的碰撞报警提示。</p><hr><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><ul><li><strong>差异化保护</strong>：搬运重物时，为防止惯性引起大轴误报，可适当放宽 A1-A3 轴灵敏度（如 150%），同时保持 A4-A6 小轴的高灵敏度以保护末端工具。</li><li><strong>特殊工艺放宽</strong>：在执行需要接触挤压力的动作（如压装）时，临时 <code>DISABLE</code> 特定轴或将 <code>Value</code> 调大，避免因工艺正常阻力导致程序中断。</li><li><strong>精细防碰撞</strong>：在狭窄空间内作业时，统一将所有轴的 <code>Value</code> 调小（如 80%），确保极轻微的触碰即可触发保护停机。</li></ul>`,18)])])}const u=t(l,[["render",n]]);export{k as __pageData,u as default};
